using namespace std;

const int N = 100005;
vector<int> adj[N];
int dist[N], n;

void dfs(int u, int fa) {
    for (int v : adj[u]) {
        if (v == fa) continue;
        dist[v] = dist[u] + 1;
        dfs(v, u);
    }
}

int findFarthest(int u) {
    fill(dist, dist + n + 1, -1);
    dist[u] = 0;
    dfs(u, -1);
    int farthest = u;
    for (int i = 1; i <= n; i++) {
        if (dist[i] > dist[farthest]) farthest = i;
    }
    return farthest;
}

int treeDiameter() {
    int u = findFarthest(1);
    int v = findFarthest(u);
    return dist[v];
}

