using namespace std;

const int N = 100005, LOGN = 20;
vector<int> adj[N];
int depth[N], fa[N][LOGN], n;

void dfs(int u, int father) {
    depth[u] = depth[father] + 1;
    fa[u][0] = father;
    for (int j = 1; j < LOGN; j++) {
        fa[u][j] = fa[fa[u][j-1]][j-1];
    }
    for (int v : adj[u]) {
        if (v == father) continue;
        dfs(v, u);
    }
}

int lca(int u, int v) {
    if (depth[u] < depth[v]) swap(u, v);
    for (int j = LOGN - 1; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) {
            u = fa[u][j];
        }
    }
    if (u == v) return u;
    for (int j = LOGN - 1; j >= 0; j--) {
        if (fa[u][j] != fa[v][j]) {
            u = fa[u][j];
            v = fa[v][j];
        }
    }
    return fa[u][0];
}

int main() {
    cin >> n;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
