const int N = 100005, LOGN = 20;
vector<int> adj[N];
int depth[N], fa[N][LOGN], diff[N], ans[N], n;

void dfs(int u, int father) {
    depth[u] = depth[father] + 1;
    fa[u][0] = father;
    for (int j = 1; j < LOGN; j++) {
        fa[u][j] = fa[fa[u][j-1]][j-1];
    }
    for (int v : adj[u]) {
        if (v == father) continue;
        dfs(v, u);
    }
}

int lca(int u, int v) {
    if (depth[u] < depth[v]) swap(u, v);
    for (int j = LOGN - 1; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) u = fa[u][j];
    }
    if (u == v) return u;
    for (int j = LOGN - 1; j >= 0; j--) {
        if (fa[u][j] != fa[v][j]) {
            u = fa[u][j]; v = fa[v][j];
        }
    }
    return fa[u][0];
}

void addPath(int u, int v, int k) {
    diff[u] += k;
    diff[v] += k;
    int p = lca(u, v);
    diff[p] -= k;
    diff[fa[p][0]] -= k;
}

void addEdgePath(int u, int v, int k) {
    diff[u] += k;
    diff[v] += k;
    int p = lca(u, v);
    diff[p] -= 2 * k;
}

void sumDfs(int u, int father) {
    ans[u] = diff[u];
    for (int v : adj[u]) {
        if (v == father) continue;
        sumDfs(v, u);
        ans[u] += ans[v];
    }
}

int main() {
