const int N = 100005;
vector<int> adj[N];
int dp[N], max1[N], max2[N], n;

void dfs1(int u, int father) {
    max1[u] = 0; max2[u] = 0;
    for (int v : adj[u]) {
        if (v == father) continue;
        dfs1(v, u);
        int val = max1[v] + 1;
        if (val > max1[u]) {
            max2[u] = max1[u];
            max1[u] = val;
        } else if (val > max2[u]) {
            max2[u] = val;
        }
    }
    dp[u] = max1[u];
}

void dfs2(int u, int father, int up) {
    for (int v : adj[u]) {
        if (v == father) continue;
        int val = (max1[v] + 1 == max1[u]) ? max2[u] : max1[u];
        dfs2(v, u, max(up + 1, val + 1));
    }
    dp[u] = max(max1[u], up);
}

int main() {
    cin >> n;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    dfs1(1, 0);
    dfs2(1, 0, 0);

    for (int i = 1; i <= n; i++) {
        cout << dp[i] << " ";
    }

    return 0;
}

