void calcSize(int u, int fa) {
    sz[u] = 1;
    max_sz[u] = 0;
    for (int v : adj[u]) {
        if (v == fa || removed[v]) continue;
        calcSize(v, u);
        sz[u] += sz[v];
        max_sz[u] = max(max_sz[u], sz[v]);
    }
}

int findCenter(int u, int fa, int tot) {
    for (int v : adj[u]) {
        if (v == fa || removed[v]) continue;
        if (sz[v] > tot / 2) return findCenter(v, u, tot);
    }
    return u;
}

void collectDist(int u, int fa, int d, vector<int>& tmp) {
    tmp.push_back(d);
    for (int v : adj[u]) {
        if (v == fa || removed[v]) continue;
        collectDist(v, u, d + 1, tmp);
    }
}

void calcAnswer(vector<int>& d, int l, int r) {
    sort(d.begin(), d.end());
    int i = 0, j = d.size() - 1;
    while (i <= j) {
        if (d[i] + d[j] <= k) {
            ans += j - i;
            i++;
        } else {
            j--;
        }
    }
}

void divide(int u) {
    calcSize(u, -1);
    int center = findCenter(u, -1, sz[u]);
    removed[center] = true;

    vector<int> all_dists;
    all_dists.push_back(0);

    for (int v : adj[center]) {
        if (removed[v]) continue;
        vector<int> tmp;
        collectDist(v, center, 1, tmp);
        calcAnswer(tmp, 0, tmp.size() - 1);
        all_dists.insert(all_dists.end(), tmp.begin(), tmp.end());
