#include <iostream>
#include <vector>
using namespace std;

const int N = 100005;
vector<pair<int, int>> adj[N];
int sz[N], n, k, ans = 0;
bool removed[N];

void calcSize(int u, int fa) {
    sz[u] = 1;
    for (auto [v, w] : adj[u]) {
        if (v == fa || removed[v]) continue;
        calcSize(v, u);
        sz[u] += sz[v];
    }
}

pair<int, int> findCenterEdge(int u, int fa, int tot) {
    int best_diff = tot, best_edge = -1;
    for (auto [v, w] : adj[u]) {
        if (v == fa || removed[v]) continue;
        int diff = abs(sz[v] - (tot - sz[v]));
        if (diff < best_diff) {
            best_diff = diff;
            best_edge = v;
        }
    }
    return {u, best_edge};
}

void collectDist(int u, int fa, int d, vector<int>& tmp) {
    tmp.push_back(d);
    for (auto [v, w] : adj[u]) {
        if (v == fa || removed[v]) continue;
        collectDist(v, u, d + w, tmp);
    }
}

void calcAnswer(vector<int>& d) {
    sort(d.begin(), d.end());
    int i = 0, j = d.size() - 1;
    while (i <= j) {
        if (d[i] + d[j] <= k) {
            ans += j - i;
            i++;
        } else {
            j--;
        }
    }
}

void divide(int u) {
    calcSize(u, -1);
    auto [cu, cv] = findCenterEdge(u, -1, sz[u]);
    if (cv == -1) return;

    removed[cu] = true;
    removed[cv] = true;

    vector<int> d1, d2;
    collectDist(cu, cv, 0, d1);
    collectDist(cv, cu, 0, d2);

    vector<int> all;
    all.insert(all.end(), d1.begin(), d1.end());
    all.insert(all.end(), d2.begin(), d2.end());
    calcAnswer(all);

    removed[cu] = false;
    removed[cv] = false;

    divide(cu);
    divide(cv);
}

int main() {
    cin >> n >> k;
    for (int i = 1; i < n; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    divide(1);

    cout << ans << endl;

    return 0;
}
